"""Evidence report, with explicit negative result and remaining framework scope."""
from common47 import *

def main():
 out=R/'outputs/eval_v1';a=read(out/'analysis.json');v=read(out/'verification.json');assert v['status']=='PASS_FROZEN_FINITE_GRID_SCREEN';assert not (R/'REPORT_MANIFEST.json').exists();fits=a['fit_summaries'];utc=now();table=['| Mechanism | Objective | rho | Future ES | Future MSE | Coverage90 | Joint NLL/65 |','|---|---|---:|---:|---:|---:|---:|']
 for row in a['tables']:table.append(f"| {row['case']} | {row['method']} | {row['rho']:g} | {row['energy']:.6f} | {row['mse']:.6f} | {row['coverage90']:.4f} | {row['nll_per65']:.6f} |")
 differences=['| Mechanism | Candidate vs full NLL | Mean ES difference | Conditional path CI95 | Seed1 / Seed2 |','|---|---|---:|---|---|']
 for row in a['paired_comparisons']:
  if row['metric']!='energy':continue
  lo,hi=row['conditional_path_bootstrap_CI95'];ss=list(row['seed_mean_differences'].values());differences.append(f"| {row['case']} | {row['candidate']} | {row['candidate_minus_reference']:+.6f} | [{lo:+.6f}, {hi:+.6f}] | {ss[0]:+.6f} / {ss[1]:+.6f} |")
 decision='Deprioritize the current fixed-feature Laplace / hybrid recipe as a new world-model framework. In this qualified screen it does not improve complete-clock likelihood training: the bistable future-energy differences are adverse in both training seeds, and OU provides no reliable future-quality advantage. The mean-clock restriction loses useful dependence, but a complete ordinary stochastic-clock model already restores it.'
 scope='Two separately fitted one-dimensional finite-grid Markov carriers, a known Gaussian mark/emission model, known initial prior and known exogenous density multiplier. Not continuous-SDE, learned high-dimensional latent-state, real-domain, history-dependent clock, informative-EOS, unknown observation-policy or causal-intervention validation. Actual physical EVAL paths are shared across density contexts; policy contexts and trained-model scores are not independent new trajectories.'
 controls='All four arms use the same 644 trainable parameters, initial weights per seed, TRAIN cohort, held-out observed-VAL criterion and precomputed minibatch schedules. Full NLL integrates the stochastic state with an exact finite-grid forward recursion and includes empty intervals. It is a complete joint-law baseline, not a deterministic or per-time-independent likelihood. No future hidden-state labels enter fitting or VAL selection. HyperNSDE MLP class definitions execute unchanged; no full original-paper reproduction is claimed.'
 caveats='Five of sixteen selections occur at the final update despite the prescribed plateau rule; zero hard caps are hit. This is not proof of universal optimization exhaustion. Laplace-only updates and complete fits are cheaper here, but exact matched-time future-quality frontiers, preprocessing cost and high-dimensional scaling are not measured. Empirical feature means use the entire TRAIN cohort once, unlike raw trajectory minibatches; this is identical data but different statistic reuse, not additional observations. Only selected and last fit checkpoints are retained. Confidence intervals resample 256 physical paths within each carrier while retaining policy/seed pairing; they are conditional on these two fitted initializations, not population uncertainty across retrainings or domains. Nominal90 coverage comes from finite64-draw empirical quantiles; even the known-process reference has sampling/finite-cohort deviation from .90.'
 evidence=f"Sixteen fresh fits, {a['formal_updates']} updates, sum of per-fit wall times {a['sum_fit_wall_seconds']:.3f}s (two concurrent CPU workers; not elapsed time or GPU hours). EVAL:54 raw groups,13824 model–origin–policy scores,512 unique physical trajectories and1536 paired history contexts,64 joint futures each. Independent NumPy/SciPy verification PASS: max ES discrepancy {v['max_energy_arithmetic_error']:.3g}, joint NLL/65 discrepancy {v['max_nll_per65_independent_error']:.3g}, covariance discrepancy {v['max_covariance_independent_error']:.3g}. All frozen weight/source/data/schedule identities checked."
 (R/'experimental_results.md').write_text('# C47 — complete joint clock/state objective screen\n\nUTC '+utc+'.\n\n'+decision+'\n\n'+evidence+'\n\n'+'\n'.join(table)+'\n\nLower is better for ES/MSE/NLL. Learned rows average two fits; reference rows use the generating process filtered on the same observed history, never the actual hidden terminal state. First scheduled future is Z32 after32 observed count cells, without an extra transition.\n\n'+'\n'.join(differences)+'\n\nPositive differences mean worse than full NLL; the table averages three paired density conditions equally. These are descriptive conditional-fit intervals, not a declaration of multi-domain statistical significance.\n\n'+controls+'\n\n'+caveats+'\n\n'+scope+'\n\nRaw samples, model bundles, configs, optimizer/last states and logs remain on the server. Compact arithmetic, coupling, mechanism diagnostics and CSV tables are mirrored locally. No EVAL-driven hyperparameter adjustment was performed.\n',encoding='utf-8')
 registry='# C47 baseline registry\n\n'+controls+'\n\nSource: HyperNSDE9d3db33ccfcf79e134d69381c6284b2692a5aef6 (selected class reuse only), TESAR-CDEa57a940310ee877cb9305b588af759d572e2be2e (review only). PCF-GAN, SigTPP and deterministic neural-SDE moment propagation are prior art, not executed headline reproductions. License metadata and selected-file hashes retained; no public redistribution.\n\n| Fit | Updates | Selected update | Observed VAL NLL/65 | Fit seconds |\n|---|---:|---:|---:|---:|\n'
 for f in fits:registry+=f"| {f['tag']} | {f['updates']} | {f['selected_step']} | {f['selected_val_nll']:.7f} | {f['elapsed_seconds']:.3f} |\n"
 registry+='\nDiscarded qualification:7 updates ×4 methods ×2 devices =56 updates, excluded from formal totals. Actual CPU median steps were .0427/.0357/.0149/.0514s for mean NLL/full NLL/Laplace/hybrid; CUDA slower in this small grid workload. Process-local affinity/BLAS settings only, no global changes. '+caveats+'\n';(R/'baseline_registry.md').write_text(registry,encoding='utf-8')
 (R/'negative_evidence.md').write_text('# C47 negative evidence\n\n'+decision+'\n\nThe analytic conditional-Poisson transform is classical, not a new theorem. PCF-GAN and SigTPP already train sequence distributions, including precomputed empirical statistics in SigTPP. HyperNSDE already has an unsplit stochastic-clock path. The restricted mean-clock result cannot support a claim that existing models lack state/clock coupling.\n\nOn the bistable carrier, Laplace-only and hybrid give worse future ES than full NLL under both seeds. A cheaper update is an unresolved cost tradeoff, not proof of a superior scalable framework. No test-driven bank/weight retuning or stronger fixture is used to rescue this recipe.\n\n'+caveats+'\n\n'+scope+'\n\nThis does not prove every Laplace-functional objective useless, or every full-likelihood method sufficient at all scales. It removes this particular positive contribution claim from the current evidence.\n',encoding='utf-8')
 (R/'hypothesis_space.md').write_text('# C47 competing explanations\n\nH0: complete stochastic-clock likelihood already captures the useful dependence. Supported within this finite-grid screen by the reference and future-law comparisons.\n\nH1: conditioning the observation clock only on a deterministic mean removes useful state-innovation dependence. The restricted arm has adverse NLL and future ES in both carriers; independent count/state covariance confirms its zero conditional innovation coupling. This is an ablation result, not a universal failure of HyperNSDE.\n\nH2: the proposed fixed Laplace bank adds necessary learning signal beyond full NLL. Not supported by the frozen future-law comparison; the bistable seed effects are adverse. No extrapolation to all feature banks.\n\nH3: apparent loss quality reflects inference/gradient/forecast-boundary errors. Direct Poisson Monte Carlo, finite differences, independent log filtering, boundary moments and full independent EVAL arithmetic pass. Remaining finite-grid/known-emission restrictions still apply.\n\nH4: the method offers a useful equal-cost advantage at scale. Unresolved, not established by lower per-step time; requires fresh checkpoint/compute protocol and unknown-emission continuous or real-domain evidence. Current evidence does not justify expensive expansion to force a positive result.\n\nH5: adverse feature loss is due to finite-bank information, weights, objective bias or finite optimization. Still competing; diagnosing them might explain this method, but is not itself evidence of a new general world-model problem.\n',encoding='utf-8')
 (R/'research_ideas.md').write_text('# C47 idea triage\n\nResearch unit remains a reusable time-series world-model framework at WorldTS scope. Dataset-specific score optimization is not the goal; a framework may use known components if their distinct interaction has independent value. Generic state-space-model expressivity alone is not a veto.\n\nCurrent tested recipe: analytically integrate conditionally Poisson observations and match joint clock/mark transforms alongside NLL. '+decision+'\n\nDo not recommend this as one of the final directions. No second or third final direction is invented. An efficiency variant remains an unselected lead, with matched-time and scalability evidence missing and substantial transform/signature prior art.\n\nNext development must start from a consequential capability and strong actual neural world-model implementations on independent domains. Repeating these toy carriers, enlarging a feature bank after EVAL, or renaming ordinary joint likelihood would provide little new information.\n',encoding='utf-8')
 final='# C47 — no final research direction accepted\n\n**Research Question:** Can a world-model learning objective preserve the coupling between stochastic physical evolution and endogenous observation timing, with useful scheduled-future simulation when observation density changes? This is a capability question; a new framework contribution is not established.\n\n**Evidence:** '+evidence+'\n\n'+decision+'\n\n**Existing Methods:** HyperNSDE unsplit dynamics already couple stochastic paths and clocks. Complete joint likelihood handles this dependence; PCF-GAN/SigTPP cover global transform/signature learning. Their actual applicability, not generic expressivity, bounds the current claim. See literature_review.md.\n\n**Proposed Idea:** The tested analytic marked-clock Laplace/hybrid recipe remains unaccepted. No final new mechanism is recommended.\n\n**Falsification:** A complete ordinary baseline restoring the capability without a new loss weakens the necessity claim; adverse hybrid future scores in both bistable seeds directly falsify the current recipe\'s improvement claim in this screen.\n\n**Feasibility:** All training/evaluation ran on the authorized server. CPU was selected by actual discarded throughput; the single RTX5090 remains available for workloads that benefit. Pinned source, frozen data/configs/seeds, checkpoints, raw paths and independent verification remain saved.\n\n**Next Experiment:** Do not tune this EVAL. A genuinely different learning interaction needs an explicitly defined reusable capability, current primary-source differentiation and a new independent protocol on stronger neural models. Any retained efficiency lead first needs a fair matched-time frontier rather than more seeds for this negative quality result.\n\n'+scope+'\n\nAccepted final directions0; overall goal ACTIVE_UNACHIEVED. Completed evidence screen is progress, not completion of discovery.\n';(R/'final_research_direction.md').write_text(final,encoding='utf-8')
 (R/'SCIENTIFIC_DECISION.md').write_text('# C47 scientific decision\n\n'+decision+'\n\n'+controls+'\n\n'+caveats+'\n\n'+scope+'\n\nNo public release or old-result deletion. C44 remains deliberately stopped and its original query protocol incomplete; this screen does not repair or complete it.\n',encoding='utf-8')
 (R/'PRIORITY_DECISION.md').write_text('# C47 priority decision\n\nDeprioritize this fixed-feature Laplace/hybrid proposal; do not launch longer runs or change features against this EVAL. Full likelihood already provides the useful capability in the qualified carriers. Cost scalability is unresolved, not ruled out universally. No accepted final framework.\n\nRetain negative evidence and shift discovery to a distinct framework-level question supported by actual source and independent-domain tests. No additional mathematical novelty condition or universal-checkpoint requirement is imposed.\n',encoding='utf-8')
 (R/'COUNT_GUIDE.md').write_text('# C47 count guide\n\n16 trained model fits =2 mechanisms ×2 initialization seeds ×4 objectives. 21200 formal updates;56 discarded qualification updates separate. 512 unique physical EVAL trajectories =256 per mechanism. Three paired observation-density histories per physical path =1536 contexts. Each case has8 learned fits plus one known-process reference, making54 raw model/policy groups and13824 model–origin–policy score entries. Neither contexts nor model repetitions multiply independent physical trajectories. Each entry uses64 joint32-step futures. Two fit seeds are not many-seed stability evidence.\n',encoding='utf-8')
 (R/'CURRENT_STATE.md').write_text('# C47 current state\n\nUTC '+utc+'. All16 fits, complete locked evaluation, independent arithmetic/filter/covariance verification and descriptive analysis complete. Figure review state is recorded separately in outputs/figures_v1/visual_qa.json. 21200 formal updates. Accepted final directions0, overall goal ACTIVE_UNACHIEVED. '+decision+'\n',encoding='utf-8')
 assert (R/'literature_review.md').exists();dump(R/'REPORT_MANIFEST.json',{'status':'COMPLETE_SCREEN_REPORTS_NOT_COMPLETE_RESEARCH_GOAL','utc':utc,'files':{p.name:sha(p) for p in R.iterdir() if p.suffix=='.md'},'analysis_sha256':sha(out/'analysis.json'),'source_sha256':sha(__file__)});print(json.dumps({'reports_written':10,'formal_fits':16,'formal_updates':21200,'accepted_final_directions':0,'decision':decision}),flush=True)
if __name__=='__main__':main()
